-- Generated by the pr-evidence lane. Only an unused installation may be removed.
-- Operational rollback disables sessions.session_pr_evidence_settings and the Cloud flag and RETAINS evidence.
DO $guard$ DECLARE later boolean; BEGIN
 IF EXISTS(SELECT 1 FROM sessions.session_pr_evidence_state)OR EXISTS(SELECT 1 FROM sessions.session_pr_evidence_wakeups)
  OR EXISTS(SELECT 1 FROM sessions.session_pr_evidence_settings WHERE enabled)
 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='pr evidence: retain evidence; disable the setting and Cloud flag instead';END IF;
 IF to_regclass('sessions.__96bulls_migrations')IS NOT NULL THEN
  EXECUTE 'SELECT EXISTS(SELECT 1 FROM sessions.__96bulls_migrations WHERE name LIKE ''upstream:%'' AND name COLLATE "C">''upstream:20261105044000_pr_evidence.sql'')' INTO later;
  IF later THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='pr evidence: later migration applied; roll it back first';END IF;
 END IF;
END $guard$;
DROP TRIGGER session_pr_evidence_after_journal ON sessions.canonical_feature_journal;
DROP TRIGGER session_pr_evidence_forget ON sessions.session_directory;
DROP FUNCTION sessions.session_pr_evidence_journal_changed(),
 sessions.session_pr_evidence_forget(),
 sessions.session_pr_evidence_scope(jsonb),
 sessions.session_pr_evidence_claim_v1(jsonb),
 sessions.session_pr_evidence_install_v1(jsonb),
 sessions.session_pr_evidence_release_v1(jsonb),
 sessions.session_pr_evidence_read_v1(jsonb),
 sessions.session_pr_evidence_enqueue_v1(jsonb);
DROP TABLE sessions.session_pr_evidence,sessions.session_pr_evidence_state,sessions.session_pr_evidence_wakeups,sessions.session_pr_evidence_settings;
DO $ledger$ BEGIN
 IF to_regclass('sessions.__96bulls_migrations')IS NOT NULL THEN
  DELETE FROM sessions.__96bulls_migrations WHERE name='upstream:20261105044000_pr_evidence.sql';
 END IF;
END $ledger$;
-- The next normal migrate reapplies the removed final ledger step.
